namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves agent and judge IChatClient instances based on environment tier.
/// </summary>
internal static class Wire
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
    /// </summary>
    public static IChatClient ResolveAgentClient(IDictionary<string, string>? modelOverrides = null)
    {
        if (!EvalEnv.UseRealAgent)
            return new StubChatClient();

        return AgentChatClientFactory.Create(modelOverrides);
    }

